VALUES
    (1, 1, NULL, 5, '배송 중 상한 부분 없이 잘 도착했습니다. 품질이 좋아서 믿고 구매할 수 있을 것 같습니다.', NULL, 1, 0, 1, '2026-06-17 17:27:00', '2026-06-17 17:27:00', 0),
    (1, 2, NULL, 4, '신선도는 좋은 편이었고 양도 적당했습니다. 기대한 수준의 상품이었습니다.', NULL, 1, 0, 1, '2026-06-16 17:24:00', '2026-06-16 17:24:00', 0),
    (1, 3, NULL, 5, '향과 식감이 좋고 신선함이 느껴졌습니다. 재구매 의사가 확실히 있습니다.', NULL, 1, 0, 1, '2026-06-15 17:21:00', '2026-06-15 17:21:00', 0),
    (1, 4, NULL, 5, '포장이 튼튼해서 상품이 잘 보호되어 있었습니다. 전체적으로 매우 만족합니다.', NULL, 1, 0, 1, '2026-06-14 17:18:00', '2026-06-14 17:18:00', 0),
    (1, 5, NULL, 5, '받자마자 상태를 확인했는데 흠집이 거의 없었습니다. 신선하고 맛도 좋았습니다.', NULL, 1, 0, 1, '2026-06-13 17:15:00', '2026-06-13 17:15:00', 0),
    (1, 6, NULL, 5, '상품 설명과 거의 동일했고 양도 적당했습니다. 다음 장보기 때 다시 살 예정입니다.', NULL, 1, 0, 1, '2026-06-12 17:12:00', '2026-06-12 17:12:00', 0),
    (1, 7, NULL, 5, '품질이 안정적이고 배송도 빠른 편이었습니다. 주변에도 추천할 만합니다.', NULL, 1, 1, 1, '2026-06-11 17:09:00', '2026-06-11 17:09:00', 0),
